package hu.synostream.android;
import android.content.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;
/** Deliberately run against installed 0.5.19 only after 0.5.20 has been publicly released. */
@RunWith(AndroidJUnit4.class) public class Android0520UpgradeTest {
 @Test public void previousAppFindsPublishedUpdateAndDownloadsIt()throws Exception{android.app.Instrumentation i=InstrumentationRegistry.getInstrumentation();Context c=i.getTargetContext();UiDevice d=UiDevice.getInstance(i);AppUpdates u=AppUpdates.get(c);i.runOnMainSync(()->{u.automatic(true);u.checked=false;u.busy=false;u.available=null;u.ready=false;u.installRequested=false;});c.getSharedPreferences("upgrade_proof",0).edit().putString("retained","github-0520-preserved").commit();c.startActivity(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));assertTrue(d.wait(Until.hasObject(By.res(c.getPackageName()+":id/update_install")),30000));assertTrue(d.hasObject(By.textContains("0.5.20")));d.findObject(By.res(c.getPackageName()+":id/update_install")).click();long end=android.os.SystemClock.elapsedRealtime()+60000;while((u.busy||!u.installRequested)&&android.os.SystemClock.elapsedRealtime()<end)Thread.sleep(100);assertTrue("System installer was launched",u.installRequested);assertTrue(u.apk().isFile());}
}
